+  const uint64_t gpr_gpa = hybrid::gpr_scratch_gpa(kScratch);
+  std::vector<uint64_t> x31_writes;
+  int nonx31_gpr_writes = 0;
+  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
+    const auto& op = bus.ops[i];
+    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
+    const uint16_t rn = static_cast<uint16_t>(op.value & 0xFFFFu);
+    if (!((op.value >> 16) & 1u)) continue;
+    if (rn == hybrid::regno_gpr(31))
+      x31_writes.push_back((uint64_t(bus.ops[i - 1].value) << 32)
