static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
static constexpr uint64_t kMstatusVsInitial = 0x200ULL;

static constexpr unsigned kPollIterations = kDmiPollIterations;

// scratch_gpa: the GUEST address of the V-register transport page (L26:
// v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
// "unset" sentinel; a non-V resume never reads it, but a V resume with the
// GPA still unset throws in the sweep (no silent transport via a bogus
// address). The simulator passes the real value from platform.main_memory.
// caps: which Andes custom CSRs the TARGET core implements (derived from its
// config.inc, supplied by the sim binary). Defaults to all() -- transport
// every CSR, the prior behavior -- so existing call sites are unchanged.
explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
                      AndesCaps caps = AndesCaps::all())
